from join_puzzle import *
p=[(.035,4,28,.4,.01,.20,11,14,.13,6),(.055,5,17,.45,.01,.24,12,15,.19,6),(.08,4,16,.45,.01,.28,13,18,.18,10),(.04,5,32,.55,.01,.25,14,16,.14,8)]
for trim,sample,seg,spur in [(5,23,(3.25,1.75,2,.4,.23),17),(7,32,(3.25,1.75,2,.4,.23),17),(8,34,(3.5,1.9,3,.7,.35),17),(8,37,(3.8,1.8,2,.48,.30),18)]:
 data=make_data(seg,spur,8,trim,sample); paths,ends,dirs,curv,ports,scores=data
 cand=candidate_data(data,115,-.30)
 for pp in p:
  mates=link2(data,cand,pp)
  res,g=assemble(data,mates,False)
  good={labels[x[1]]:int(q[1]+1) for x,q in res.items() if q and x[0]==0 and q[0]==1}
  node={j//2 for z in g.values() for j in z}
  print(trim,sample,pp,len(good), good, 'reach',sum(len(paths[i]) for i in node), 'match',len(mates),flush=True)
