from flow_puzzle import *
m,s=segment4(4.,1.60,2,.41,.15,1.75)
for x,step,ys in [(lx,1,l),(rx,-1,r)]:
 m[:, (slice(x,x+20) if step>0 else slice(x-19,x+1))]=0
 for y in ys.astype(int):
  for k in range(57):
   yc=y+int(np.argmax(s[y-4:y+5,x+k*step]))-4
   m[yc-1:yc+2,x+k*step]=1
sk=skeleton(m.copy())
all_es=graph(sk)
ee=simplified(all_es,16)
for j,es in enumerate([all_es,ee]):
 print('n',j)
 for a,b,p in es:
  relevant=((p[:,0]<540)&(abs(p[:,1]-1268)<16))
  if relevant.any():
   print(len(p),p[0],p[-1],p[relevant][0])
cv2.imwrite('puzzle_debug_crop.jpg',(sk[1220:1325,460:810]*255))
'@ | python -"

